106	        }
107	        String code = owner.getCustomerCode();
108	        if (code != null) {
109	            int hyphen = code.indexOf('-');
110	            return hyphen >= 0 ? code.substring(0, hyphen) : code;
111	        }
112	        return Regions.forPostcode(owner.getPostcode());
113	    }
114	
115	    /**
116	     * Determine an owner's membership level, a number from {@code 1} to {@code 3} assigned on
117	     * create. It starts at {@code 1}, gains {@code 1} when an email address is present, and gains
118	     * {@code 1} when the owner has no namesakes (its {@code namesakeCount} is {@code 0}), capped at
119	     * {@code 3}. A null or absent namesake count is treated as not being zero, so it contributes
