121	     */
122	    default Integer formatMembershipLevel(Owner owner) {
123	        if (owner == null) {
124	            return null;
125	        }
126	        int level = 1;
127	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
128	        if (hasEmail) {
129	            level++;
130	        }
131	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
132	        if (uniqueName) {
133	            level++;
134	        }
135	        return Math.min(level, 3);
