145	        if (owner == null || owner.getCustomerCode() == null) {
146	            return null;
147	        }
148	        String code = owner.getCustomerCode();
149	        int sum = 0;
150	        boolean dbl = true;
151	        for (int i = code.length() - 1; i >= 0; i--) {
152	            char c = code.charAt(i);
153	            if (c < '0' || c > '9') {
154	                continue;
155	            }
